export function padStart(input, n = 2) {
  const str = input.toString(),
    isNeg = str.charAt(0) === "-",
    abs = isNeg ? str.slice(1) : str,
    padded = abs.length < n ? ("0".repeat(n) + abs).slice(-n) : abs;

  return isNeg ? "-" + padded : padded;
}

